<!--
 * 任务分组（列表页）
 *
 * @path apps\cronjob-web\src\views\jobGroup\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 任务分组（列表页）
 * <p>消费后端契约 JobGroupController（src/api/jobGroup.ts，auto-generated by bash/gen-contract.py）：
 * 顶部以 groupStats() 展示分组统计（字段兼容取值 jobGroup/total/running/paused），
 * 行操作支持「暂停该组」pauseByGroup、「恢复该组」resumeByGroup、「触发该组」triggerByGroup；
 * 另提供「按分组查看任务」：输入 jobGroup 后调 pageByGroup 展示该分组任务列表。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeGridProps } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { ElButton, ElMessage, ElMessageBox, ElInput, h } from 'element-plus';
import { ref } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { groupStats, pageByGroup, pauseByGroup, resumeByGroup, triggerByGroup } from '#/api/jobGroup';
import type { JobVO } from '#/api/models';

defineOptions({ name: 'JobGroupManagement' });

/** 分组统计行类型：字段由后端返回，取值需兼容（jobGroup / total / running / paused 等） */
type GroupStatsRow = Record<string, unknown>;

/** 从统计行中安全提取分组名称 */
function getGroupName(row: GroupStatsRow): string {
  return String(row.jobGroup ?? '');
}

const statsGridOptions: VxeGridProps<GroupStatsRow> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'jobGroup', title: '分组名称', width: 200 },
    { field: 'total', title: '任务总数', width: 120 },
    { field: 'running', title: '运行中', width: 120 },
    { field: 'paused', title: '已暂停', width: 120 },
    {
      field: 'action',
      title: '操作',
      width: 320,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const groupRow = row as GroupStatsRow;
          return h('div', { class: 'flex gap-1' }, [
            h(ElButton, { size: 'small', link: true, type: 'danger', onClick: () => handlePauseGroup(groupRow) }, () => '暂停该组'),
            h(ElButton, { size: 'small', link: true, type: 'success', onClick: () => handleResumeGroup(groupRow) }, () => '恢复该组'),
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleTriggerGroup(groupRow) }, () => '触发该组'),
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleViewGroup(groupRow) }, () => '查看任务'),
          ]);
        },
      },
    },
  ],
  height: 320,
  proxyConfig: {
    ajax: {
      query: async () => {
        const items = await groupStats();
        return { items, total: items.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, zoom: true },
};

const [StatsGrid, statsGridApi] = useYDSZVxeGrid({ gridOptions: statsGridOptions });

/** 当前按分组查看的分组名称（为空时任务网格不发起请求） */
const viewGroup = ref('');

const taskGridOptions: VxeGridProps<JobVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'jobName', title: '任务名称', width: 180 },
    { field: 'jobKey', title: '任务标识', width: 140 },
    { field: 'cronExpression', title: 'Cron', width: 160 },
    { field: 'handler', title: '执行器', width: 140 },
    { field: 'jobType', title: '类型', width: 100 },
    { field: 'createdAt', title: '创建时间', width: 160 },
  ],
  height: 320,
  pagerConfig: { pageSize: 10, pageSizes: [10, 20, 50] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        if (!viewGroup.value) {
          return { items: [], total: 0 };
        }
        const res = await pageByGroup(
          { jobGroup: viewGroup.value },
          { page: pageInfo.currentPage, size: pageInfo.pageSize, ...formValues },
        );
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, zoom: true },
};

const [TaskGrid, taskGridApi] = useYDSZVxeGrid({ gridOptions: taskGridOptions });

async function handlePauseGroup(row: GroupStatsRow) {
  const jobGroup = getGroupName(row);
  if (!jobGroup) return;
  try {
    await pauseByGroup({ jobGroup });
    ElMessage.success('分组已暂停');
    statsGridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleResumeGroup(row: GroupStatsRow) {
  const jobGroup = getGroupName(row);
  if (!jobGroup) return;
  try {
    await resumeByGroup({ jobGroup });
    ElMessage.success('分组已恢复');
    statsGridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleTriggerGroup(row: GroupStatsRow) {
  const jobGroup = getGroupName(row);
  if (!jobGroup) return;
  try {
    await ElMessageBox.confirm(`确定立即触发分组「${jobGroup}」下全部任务吗？`, '触发确认', { type: 'warning' });
    await triggerByGroup({ jobGroup });
    ElMessage.success('分组触发成功');
  } catch {
    // 用户取消或请求失败
  }
}

function handleViewGroup(row: GroupStatsRow) {
  const jobGroup = getGroupName(row);
  if (!jobGroup) return;
  viewGroup.value = jobGroup;
  taskGridApi.query();
}

function handleViewByInput() {
  const jobGroup = viewGroup.value.trim();
  if (!jobGroup) {
    ElMessage.warning('请输入分组名称');
    return;
  }
  taskGridApi.query();
}
</script>

<template>
  <Page auto-content-height>
    <StatsGrid table-title="分组统计" />
    <div class="mt-4 flex items-center gap-2">
      <ElInput
        v-model="viewGroup"
        class="w-64"
        placeholder="输入分组名称，查看该组任务"
        clearable
        @keyup.enter="handleViewByInput"
      />
      <ElButton type="primary" @click="handleViewByInput">查询</ElButton>
    </div>
    <TaskGrid class="mt-4" table-title="分组任务（pageByGroup）" />
  </Page>
</template>